up":"","title":"Nastavuje výstupy IIC karty s 8 analogovými výstupy","formula":"Sets 8 IIC analog outputs","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["AO0","input","Int","AO 0","Hodnota analogového výstupu AO 0","0"],["AO1","input","Int","AO 1","Hodnota analogového výstupu AO 1","0"],["AO2","input","Int","AO 2","Hodnota analogového výstupu AO 2","0"],["AO3","input","Int","AO 3","Hodnota analogového výstupu AO 3","0"],["AO4","input","Int","AO 4","Hodnota analogového výstupu AO 4","0"],["AO5","input","Int","AO 5","Hodnota analogového výstupu AO 5","0"],["AO6","input","Int","AO 6","Hodnota analogového výstupu AO 6","0"],["AO7","input","Int","AO 7","Hodnota analogového výstupu AO 7","0"],["Addr","parameter","Int","Address","Adresa modulu na sběrnici IIC","0"]],"notes":["Modul zapisuje nastavené hodnoty vstupů AO0 až AO7 do příslušných výstupů karty s adresou Addr na sběrnici IIC."],"tables":[]},{"name":"IIC_8xDO","category":"I/O","group":"","title":"Nastavuje výstupy IIC karty s 8 binárními výstupy","formula":"Sets 8 IIC digital outputs","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["DO0","input","Boolean","DO 0","Hodnota binárního výstupu DO 0","0"],["DO1","input","Boolean","DO 1","Hodnota binárního výstupu DO 1","0"],["DO2","input","Boolean","DO 2","Hodnota binárního výstupu DO 2","0"],["DO3","input","Boolean","DO 3","Hodnota binárního výstupu DO 3","0"],["DO4","input","Boolean","DO 4","Hodnota binárního výstupu DO 4","0"],["DO5","input","Boolean","DO 5","Hodnota binárního výstupu DO 5","0"],["DO6","input","Boolean","DO 6","Hodnota binárního výstupu DO 6","0"],["DO7","input","Boolean","DO 7","Hodnota binárního výstupu DO 7","0"],["Addr","parameter","Int","Address","Adresa modulu na sběrnici IIC","0"]],"notes":["Modul zapisuje nastavené hodnoty vstupů DO0 až DO7 do příslušných výstupů karty s adresou Addr na sběrnici IIC."],"tables":[]},{"name":"IIC_9xDI","category":"I/O","group":"","title":"Čte vstupy IIC karty s 9 binárními vstupy","formula":"Returns 9 IIC digital input. Emulate by \"ASDFGHJKL\" keys.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Addr","parameter","Int","Address","Adresa modulu na sběrnici IIC","0"],["DI0","output","Boolean","DI 0","Hodnota binárního vstupu DI 0","-"],["DI1","output","Boolean","DI 1","Hodnota binárního vstupu DI 1","-"],["DI2","output","Boolean","DI 2","Hodnota binárního vstupu DI 2","-"],["DI3","output","Boolean","DI 3","Hodnota binárního vstupu DI 3","-"],["DI4","output","Boolean","DI 4","Hodnota binárního vstupu DI 4","-"],["DI5","output","Boolean","DI 5","Hodnota binárního vstupu DI 5","-"],["DI6","output","Boolean","DI 6","Hodnota binárního vstupu DI 6","-"],["DI7","output","Boolean","DI 7","Hodnota binárního vstupu DI 7","-"],["DI8","output","Boolean","DI 8","Hodnota binárního vstupu DI 8","-"]],"notes":["Modul čte hodnoty binárních vstupů karty s adresou Addr na sběrnici IIC a uloží je do příslušných výstupů DI0 až DI8. Pokud je modul vybrán během spuštěné simulace, lze hodnoty DI0 až DI8 měnit z 0 na 1 a naopak pomocí kláves A S D F G H J K a L."],"tables":[]},{"name":"IIC_9xDICnt","category":"I/O","group":"","title":"Čte vstupy a hodnoty čítačů IIC karty s 9 binárními vstupy","formula":"Returns 9 IIC digital input with counters. Emulate by \"ASDFGHJKL\" keys.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Addr","parameter","Int","Address","Adresa modulu na sběrnici IIC","0"],["DI0","output","Boolean","DI 0","Hodnota binárního vstupu DI 0","-"],["DI1","output","Boolean","DI 1","Hodnota binárního vstupu DI 1","-"],["DI2","output","Boolean","DI 2","Hodnota binárního vstupu DI 2","-"],["DI3","output","Boolean","DI 3","Hodnota binárního vstupu DI 3","-"],["DI4","output","Boolean","DI 4","Hodnota binárního vstupu DI 4","-"],["DI5","output","Boolean","DI 5","Hodnota binárního vstupu DI 5","-"],["DI6","output","Boolean","DI 6","Hodnota binárního vstupu DI 6","-"],["DI7","output","Boolean","DI 7","Hodnota binárního vstupu DI 7","-"],["DI8","output","Boolean","DI 8","Hodnota binárního vstupu DI 8","-"],["Cnt0","output","Word","Counter 0","Hodnota čítače pulzů na vstupu DI 0","-"],["Cnt1","output","Word","Counter 1","Hodnota čítače pulzů na vstupu DI 1","-"],["Cnt2","output","Word","Counter 2","Hodnota čítače pulzů na vstupu DI 2","-"],["Cnt3","output","Word","Counter 3","Hodnota čítače pulzů na vstupu DI 3","-"],["Cnt4","output","Word","Counter 4","Hodnota čítače pulzů na vstupu DI 4","-"],["Cnt5","output","Word","Counter 5","Hodnota čítače pulzů na vstupu DI 5","-"],["Cnt6","output","Word","Counter 6","Hodnota čítače pulzů na vstupu DI 6","-"],["Cnt7","output","Word","Counter 7","Hodnota čítače pulzů na vstupu DI 7","-"],["Cnt8","output","Word","Counter 8","Hodnota čítače pulzů na vstupu DI 8","-"]],"notes":["Modul čte hodnoty binárních vstupů karty s adresou Addr na sběrnici IIC a uloží je do příslušných výstupů DI0 až DI8. Mimo to čte hodnoty čítačů pulzů na jednotlivých vstupech a uloží je do příslušných výstupů Cnt0 až Cnt8.","Pokud je modul vybrán během spuštěné simulace, lze hodnoty DI0 až DI8 měnit z 0 na 1 a naopak pomocí kláves A S D F G H J K a L. Nasimulování pulzů se rovněž projeví na příslušných čítačích."],"tables":[]},{"name":"IRC","category":"I/O","group":"","title":"Zpracovává připojené IRC čidlo","formula":"Incremental counter. Emulate by \"+\", \"-\" keys","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Sync","input","Boolean","Synchronize","Pokud je =1, je Cnt synchronizován s Null","0"],["Cnt","output","Long","Counter","Hodnota čítače","-"],["Null","output","Int","NullCounter","Hodnota čítače nulovaného null pulzem","-"]],"notes":["Modul zpracovává IRC čidlo připojené k binárním vstupům PLC (fáze1 na DI6, fáze2 na DI7 a nulovací pulz na DI5). Pokud je modul vybrán během spuštěné simulace, lze hodnotu čítače měnit pomocí kláves + a -."],"tables":[]},{"name":"ReadAI","category":"I/O","group":"","title":"Čte hodnoty analogových vstupů PLC","formula":"Read single analog channel. Emulate by \"+\", \"-\" keys","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Ch","input","Int","Channel","Číslo kanálu analogového vstupu","0"],["Out","output","Int","Output","Hodnota vstupu","-"]],"notes":["Modul čte hodnotu čítače na kanálu Ch. Každý analogový vstup je možné číst jako pomalý nebo rychlý vstup. Pomalé vstupy mají sudá čísla kanálů 0, 2, 4, ... 14. Rychlé vstupy mají lichá čísla kanálů 1, 3, 5, ... 15.","V současné verzi FW jsou pomalé vstupy průměrovány ze 64 vzorků a jsou obnovovány s periodou 640 ms. Rychlé vstupy jsou průměrovány z 8 vzorků a jsou obnovovány s periodou 80 ms (12.5 Hz).","Pokud je modul vybrán během spuštěné simulace, lze hodnotu výstupu Cnt měnit pomocí kláves + a -."],"tables":[]},{"name":"ReadDallas","category":"I/O","group":"","title":"Čte hodnotu teploty z teploměru Dallas DS18B20","formula":"Reads temperature from Dallas DS18B20.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Code","parameter","Long","Rom Code","Unikátní kód teploměru","0"],["St","output","Boolean","Status","Po úspěšném čtení je nastaven na logickou 1","-"],["T","output","Int","Temperature","Přečtená teplota","-"]],"notes":["Modul čte teplotu z jednoho teploměru Dallas DS18B20, který je identifikován unikátním kódem na vstupu Code. Přečtená teplota je uložena do výstupu T. Výstup St zobrazuje stav čtení (=1..úspěch, =0..čtení selhalo)","Tento modul by měl být použit v procesu \"Timer 1s\"!"],"tables":[]},{"name":"StepDriver","category":"I/O","group":"","title":"Ovládá krokový motor generováním impulsů CLK a DIR","formula":"Controls step driver.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Start","input","Boolean","Start","Spustí pohyb motoru k poloze dané vstupem Posit","0"],["Preset","input","Boolean","Preset","Nastaví polohu motoru (výstup Pos) na hodnotu vstupu PrPos. Lze provést jen pokud motor stojí (výstup Run = 0).","0"],["Speed","input","Int","Speed","Požadovaná rychlost motoru. Rozsah: 0-255. Hodnota 0 zastaví pohyb. Jednotka: 10 Hz. Maximální frekvence je tedy 2550 kroků/s.","0"],["StartS","input","Int","Start Speed","Počáteční hodnota rychlosti. Od této rychlosti se uplatní zadané zrychlení (rampa).","32"],["Accel","input","Int","Acceleration","Požadovaná strmost rampy rychlosti. Rozsah: 1-255. Vyšší hodnota znamené strmější rozjezd a brždění.","64"],["Posit","input","Long","Position","Požadovaná cílová poloha motoru. Použije se pokud je vstup Start = 1.","0"],["PrPos","input","Long","Preset Pos.","Předvolba polohy pro operaci Preset.","0"],["Run","output","Boolean","Run","Pokud je motor v chodu, je na výstupu Run hodnota 1.","-"],["Spd","output","Int","Actual speed","Okamžitá hodnota rychlosti.","-"],["Pos","output","Long","Actual pos.","Okamžitá poloha motoru.","-"]],"notes":["Modul ovládá krokový motor pomocí impulsů CLK a směru DIR (v případě jednotky P3+ to jsou výstupy Out0 a Out1). Jednotlivé příkazy se ovládají pomocí logických vstupů En, Start a Preset následovně:","Je-li aktivní vstup En, při každém provedení tohoto bloku se použijí hodnoty na vstupech Speed, StartS a Accel a aktualizují se všechny 3 výstupy. Tak lze během chodu motoru měnit rychlost pohybu. Skutečná rychlost se přibližuje k požadované rychlosti na vstupu Speed se zrychlením Accel. Zrychlení se uplatňuje až při rychlostech větších než StartSpeed. Pokud je požadovaná rychlost na vstupu Speed nulová, pohyb se (po rampě) zastaví a poté výstup Run přejde do stavu 0.","Vstupem Start se spustí pohyb motoru od aktuální polohy Pos k cílové poloze dané vstupem Posit. Pokud při tom již motor byl v pohybu (Run=1), provede se aktualizace cílové polohy. V případě, že tato cílová poloha vyžaduje změnu směru pohybu, dojde k zastavení motoru (po dané rampě) a rozjezdu opačným směrem.","Vstup Preset umožňuje přepsat aktuální polohu na výstupu Pos hodnotou na vstupu PrPos. Toto lze provést jen pokud není motor v pohybu (výstup Run = 0). Používá se při kalibraci polohy motoru najetím na známé místo a zápisem polohy tohoto místa na výstup Pos."],"tables":[]},{"name":"Comparator","category":"Main","group":"Comparators","title":"Porovnává hodnoty typu int","formula":"Compares values A and B","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["A","input","Int","A","Hodnota A","0"],["B","input","Int","B","Hodnota B","0"],["AGtB","output","Boolean","A greater than B","Pokud je A>B, pak je =1, jinak je =0","-"],["AEqB","output","Boolean","A equal B","Pokud je A=B, pak je =1, jinak je =0","-"],["ALtB","output","Boolean","A less than B","Pokud je A<B, pak je =1, jinak je =0","-"]],"notes":["Modul porovnává vstupní hodnoty A a B a podle jejich hodnot nastaví právě jeden z výstupů na hodnotu 1. Zbylé dva výstupy budou vynulovány."],"tables":[]},{"name":"HystComparator","category":"Main","group":"Comparators","title":"Porovnává hodnoty typu int s hysterezí","formula":"Compares values A and B with hysteresis","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["A","input","Int","A","Hodnota A","0"],["B","input","Int","B","Hodnota B","0"],["HalfHyst","parameter","Int","Half hysteresis","Poloměr hystereze","0"],["AGtB","output","Boolean","A greater than B","Zobrazení stavu A>B","-"],["AEqB","output","Boolean","A equal B","Zobrazení stavu A=B","-"],["ALtB","output","Boolean","A less than B","Zobrazení stavu A<B","-"]],"notes":["Modul funguje podobně jako Comparator, avšak s tím rozdílem, že porovnává vstupní hodnoty A a B s nastavenou hysterezí. Výstup AGtB se nastavuje, když A>(B+HalfHyst) a nuluje, když A<(B-HalfHyst). Obdobně výstup ALtB nastavuje podmínka A<(B-HalfHyst) a nuluje podmínka A>(B+HalfHyst). Hodnota výstupu AEqB odpovídá podmínce A>=(B-HalfHyst) a současně A<=(B+HalfHyst)."],"tables":[]},{"name":"InRange","category":"Main","group":"Comparators","title":"Zjišťuje, zda je hodnota v daném intervalu","formula":"Returns 1 if X is between L and H","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Long","X","Vstupní hodnota","0"],["L","parameter","Int","Low","Dolní mez intervalu","0"],["H","parameter","Int","High","Horní mez intervalu","0"],["Y","output","Boolean","Y","Výstupní hodnota","-"]],"notes":["Modul InRange porovná hodnotu vstupu X se zadanými mezemi intervalu. V případě, kdy je L<=H je hodnota výstupu Y rovna podmínce (X>=L) a zároveň (X<H), tj. X leží mezi L (včetně) a H. Pokud L>H, pak hodnota výstupu odpovídá podmínce (X<L) nebo Toto pojetí umožňuje např. použití modulu jako časového spínače, kdy jsou na vstup X přivedeny hodiny. Parametr L pak určuje čas sepnutí a H čas vypnutí, přičemž je ošetřen i přechod přes půlnoc."],"tables":[]},{"name":"LComparator","category":"Main","group":"Comparators","title":"Porovnává hodnoty typu Long","formula":"Compares values A and B","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["A","input","Long","A","Hodnota A","0"],["B","input","Long","B","Hodnota B","0"],["AGtB","output","Boolean","A greater than B","Pokud je A>B, pak je =1, jinak je =0","-"],["AEqB","output","Boolean","A equal B","Pokud je A=B, pak je =1, jinak je =0","-"],["ALtB","output","Boolean","A less than B","Pokud je A<B, pak je =1, jinak je =0","-"]],"notes":["Modul porovnává vstupní hodnoty A a B a podle jejich hodnot nastaví právě jeden z výstupů na hodnotu 1. Zbylé dva výstupy budou vynulovány."],"tables":[]},{"name":"MCompare","category":"Main","group":"Comparators","title":"Porovnání vstupní hodnoty s více hodnotami typu Long","formula":"Compares values X with values C1..Cn","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Long","Input","Vstupní hodnota","0"],["C1 - Cn","parameters","Long","C1 - Cn","Value inputs","0"],["N","output","Int","Index","Output","-"]],"notes":["C1 - Cn parametry Long C1 - Cn Vstupy hodnot 0 N výstup Int Index Výstup - Modul hledá hodnotu na vstupu X mezi konstantami na vstupech C1-Cn a vrátí pořadové číslo první konstanty stejné hodnoty jako je na vstupu X. Pokud není shoda nalezena, je výstup N vynulován.","Počet vstupů N tohoto modulu je uživatelsky nastavitelný v rozsahu 1 - 16."],"tables":[]},{"name":"Bits2Int","category":"Main","group":"Conversion","title":"Složí hodnotu typu int z 16 binárních vstupů","formula":"Converts bits to int","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["B0","input","Boolean","Bit 0","Vstupní hodnota bitu řádu 0","0"],["B1","input","Boolean","Bit 1","Vstupní hodnota bitu řádu 1","0"],["B2","input","Boolean","Bit 2","Vstupní hodnota bitu řádu 2","0"],["B3","input","Boolean","Bit 3","Vstupní hodnota bitu řádu 3","0"],["B4","input","Boolean","Bit 4","Vstupní hodnota bitu řádu 4","0"],["B5","input","Boolean","Bit 5","Vstupní hodnota bitu řádu 5","0"],["B6","input","Boolean","Bit 6","Vstupní hodnota bitu řádu 6","0"],["B7","input","Boolean","Bit 7","Vstupní hodnota bitu řádu 7","0"],["B8","input","Boolean","Bit 8","Vstupní hodnota bitu řádu 8","0"],["B9","input","Boolean","Bit 9","Vstupní hodnota bitu řádu 9","0"],["B10","input","Boolean","Bit 10","Vstupní hodnota bitu řádu 10","0"],["B11","input","Boolean","Bit 11","Vstupní hodnota bitu řádu 11","0"],["B12","input","Boolean","Bit 12","Vstupní hodnota bitu řádu 12","0"],["B13","input","Boolean","Bit 13","Vstupní hodnota bitu řádu 13","0"],["B14","input","Boolean","Bit 14","Vstupní hodnota bitu řádu 14","0"],["B15","input","Boolean","Bit 15","Vstupní hodnota bitu řádu 15","0"],["Y","output","Int","Y","Výstupní hodnota","-"]],"notes":["Výsledná hodnota výstupu Y bude složena z jednotlivých vstupních bitů. Každý vstup B0 až B15 zastupuje příslušný řád v binární soustavě. Y=B0.20 +B1.21 +...+B15.215"],"tables":[]},{"name":"Int2Bits","category":"Main","group":"Conversion","title":"Zpřístupňuje jednotlivé bity hodnoty typu int","formula":"Expands int into bits","pins":[["X","input","Int","X","Vstupní hodnota","0"],["B0","output","Boolean","Bit 0","Nejnižší bit hodnoty X","-"],["B15","output","Boolean","Bit 15","Nejvyšší bit hodnoty X","-"]],"notes":["Modul zpřístupňuje jednotlivé bity hodnoty vstupu X."],"tables":[]},{"name":"CalibTransf","category":"Main","group":"Filters","title":"Tříbodová lineární transformace hodnoty typu int","formula":"Transfer X calibrated on XMin-XCenter-XMax to Y in range YMin-YCenter-YMax.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Int","X","Vstupní hodnota","0"],["XMax","parameter","Int","Maximum X","Maximální hodnota vstupu X","0"],["XMid","parameter","Int","Middle X","Střední hodnota vstupu X","0"],["XMin","parameter","Int","Minimum X","Minimální hodnota vstupu X","0"],["YMax","parameter","Int","Maximum Y","Maximální hodnota výstupu Y","0"],["YMid","parameter","Int","Middle Y","Střední hodnota výstupu Y","0"],["YMin","parameter","Int","Minimum Y","Minimální hodnota výstupu Y","0"],["Y","output","Int","Y","Výstupní hodnota","-"]],"notes":["Parametry XMin, XMid a XMax rozdělují rozsah vstupu X na 4 intervaly. Pokud je X<=XMin, pak bude na výstupu Y hodnota YMin. Obdobně v případě, kdy je X>=XMax, bude na výstupu Y hodnota YMax. Vstupním hodnotám v intervalu XMin až XMid odpovídá poměrná výstupní hodnota YMin až YMid a analogicky vstupním hodnotám v intervalu XMid až XMax odpovídá poměrná výstupní hodnota YMid až YMax.","Grafické znázornění je následujícím obrázku."],"tables":[]},{"name":"DelayFilter","category":"Main","group":"Filters","title":"Filtruje krátké pulzy binární hodnoty","formula":"Input signal must persist for specified cycles (Delay) to appear on output","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["In","input","Boolean","Input","Vstupní signál","0"],["Dly","parameter","Int","Delay","Délka prodlevy","0"],["Cnt","output","Int","Counter","Odpočet zbývajících cyklů","-"],["Out","output","Boolean","Output","Výstupní signál","-"]],"notes":["Pokud se na vstupu In objeví logická 1, začne odpočet průchodů cyklem procesu, ve kterém je modul zpracováván. Počáteční hodnota odpočtu Cnt odpovídá velikosti parametru Dly a s každým cyklem je snížena o 1 dokud je vstup aktivní (=1). Po odpočítání do 0 se na výstup Out nastaví logická 1.","Kdykoli je vstup In vynulován, je vynulován rovněž výstup Out a Cnt nastaven na hodnotu parametru Dly.","Jestliže například chcete odfiltrovat pulzy kratší než 5s, umístěte modul do procesu \"Timer 1s\" a nastavte parametr Dly na 5. Pulzy, které projdou na výstup Out budou zkráceny o 5s."],"tables":[]},{"name":"Filter","category":"Main","group":"Filters","title":"Filtr realizující časové zpoždění 1. řádu","formula":"First-order filter","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Int","Input","Vstupní hodnota pro filtrování","0"],["T","parameter","Int","Time","Časová konstanta filtru","10"],["Y","output","Int","Output","Filtrovaná hodnota","-"]],"notes":["Modul filtruje vstupu X. Zpoždění filtru (doba, za kterou výstup dosáhne cca 63% vstupní hodnoty) je určena parametrem T."],"tables":[]},{"name":"ILimiter","category":"Main","group":"Filters","title":"Omezuje hodnotu na daný interval","formula":"Value is limited in range Min..Max","pins":[["X","input","Long","X","Vstupní hodnota","0"],["Max","parameter","Int","Max","Maximální přípustná hodnota výstupu","0"],["Min","parameter","Int","Min","Minimální přípustná hodnota výstupu","0"],["Y","output","Int","Y","Omezená hodnota","-"]],"notes":["Modul omezuje hodnotu vstupu X na interval daný parametry Min a Max. Pokud je hodnota X < Min, bude na výstupu Y hodnota Min. Obdobně pokud je X > Max, bude na výstupu Y hodnota Max. Vstupní hodnota X má zvětšený rozsah typu Long."],"tables":[]},{"name":"LLimiter","category":"Main","group":"Filters","title":"Omezuje hodnotu na daný interval","formula":"Value is limited in range Min..Max","pins":[["X","input","Long","X","Vstupní hodnota","0"],["Max","parameter","Long","Max","Maximální přípustná hodnota výstupu","0"],["Min","parameter","Long","Min","Minimální přípustná hodnota výstupu","0"],["Y","output","Long","Y","Omezená hodnota","-"]],"notes":["Modul omezuje hodnotu vstupu X na interval daný parametry Min a Max. Pokud je hodnota X < Min, bude na výstupu Y hodnota Min. Obdobně pokud je X > Max, bude na výstupu Y hodnota Max."],"tables":[]},{"name":"Ramp","category":"Main","group":"Filters","title":"Vytváří rampu pro skokově měněnou hodnotu","formula":"Ramped value move","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Int","X","Vstupní hodnota","0"],["SU","parameter","Int","Step up","Maximální změna výstupní hodnoty směrem nahoru","0"],["SD","parameter","Int","Step down","Maximální změna výstupní hodnoty směrem dolů","0"],["Y","output","Int","Y","Výstupní hodnota","-"]],"notes":["Je-li na vstupu X hodnota jiná, než je hodnota na výstupu Y, bude se modul snažit hodnotu Y k hodnotě X přiblížit. V každém cyklu se však Y zvýší maximálně o hodnotu parametru SU, případně sníží maximálně o hodnotu parametru SD.","Při skokové změně vstupu X tedy dochází k plynulé změně výstupu Y po rampě, jejíž strmost směrem nahoru je určena parametrem SU a směrem dolů parametrem SD."],"tables":[]},{"name":"AdvCounter","category":"Main","group":"Other","title":"Čítač událostí s omezením rozsahu a přednastavením","formula":"Increases Y by Step on Trigger 0->1 event","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Tr","input","Boolean","Trigger","Při přechodu z 0 do 1 se k výstupu Y přičte St","0"],["Rst","input","Boolean","Reset","Je-li aktivní (=1), je výstup Y nulován","0"],["Pres","input","Boolean","Preset","Je-li aktivní (=1), je výstup Y nastaven na hodnotu PV","0"],["EnH","input","Boolean","EnableH","Je-li aktivní (=1), je výstup Y shora omezen hodnotou Max","0"],["EnL","input","Boolean","EnableL","Je-li aktivní (=1), je výstup Y zdola omezen hodnotou Min","0"],["PV","parameter","Int","PresetVal","Přednastavená hodnota čítače. Aktivuje se vstupem Preset.","0"],["Max","parameter","Int","Maximum","Horní mez čítače","0"],["Min","parameter","Int","Minimum","Dolní mez čítače","0"],["St","parameter","Int","Step","Velikost kroku zvyšování hodnoty výstupu Y","1"],["Y","output","Int","Y","Stav čítače","-"],["H","output","Boolean","High","Indikuje dosažení hodnoty Max. Je nastaven pokud Y >= Max.","-"],["L","output","Boolean","Low","Indikuje dosažení hodnoty Min. Je nastaven pokud Y <= Min.","-"]],"notes":["Modul sleduje stav vstupu Tr. Při výskytu náběžné hrany (přechodu z 0 do 1) zvýší hodnotu výstupu Y o hodnotu parametru St. Je-li aktivní vstup Rst, je hodnota výstupu Y nulována.","Je-li aktivní vstup Preset, je hodnota výstupu Y nastavena na hodnotu parametru PV.","Je-li aktivní vstup EnH resp. EnL, je hodnota výstupu Y omezena shora hodnotou parametru Max, resp. zdola hodnotou parametru Min. Výstupy H resp. L jsou nastaveny pokud hodnota výstupu Y dosáhne mezní hodnoty dané parametry Max resp. Min. Tyto výstupy pracují nezávisle na povolení omezení výstupu vstupy EnH a EnL."],"tables":[]},{"name":"Counter","category":"Main","group":"Other","title":"Čítač událostí","formula":"Increases Y by Step on Trigger 0->1 event","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Tr","input","Boolean","Trigger","Při přechodu z 0 do 1 se k výstupu Y přičte St","0"],["Rst","input","Boolean","Reset","Je-li aktivní (=1), je výstup Y nulován","0"],["St","parameter","Int","Step","Velikost kroku zvyšování hodnoty výstupu Y","1"],["Y","output","Int","Y","Stav čítače","-"]],"notes":["Modul sleduje stav vstupu Tr. Při výskytu náběžné hrany (přechodu z 0 do 1) zvýší hodnotu výstupu Y o hodnotu parametru St. Je-li aktivní vstup Rst, je hodnota výstupu Y nulována."],"tables":[]},{"name":"Logger","category":"Main","group":"Other","title":"Zaznamenává data do archivační paměti","formula":"Writes data log into archive memory","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["I1 - In","input","Int","Ints","Vstupy typu Int","0"],["L1 - Ln","input","Long","Longs","Vstupy typu Long","0"],["F1 - Fn","input","Float","Floats","Vstupy typu Float","1"],["Idx","output","Int","Index","Index (číslo řádku archivu) pro další zápis","-"]],"notes":["Logger zapisuje hodnoty signálů na vstupech Ix, Lx a Fx do archivační paměti PLC pro jejich pozdější vyčítání pomocí PC. Zápis proběhne v každém cyklu, ve kterém je na vstupu En hodnota 1. Kromě hodnot vstupních signálů je součástí každého záznamu systémový čas PLC.","V konfiguračním dialogu lze zvolit počet vstupů typu Int, Long a Float, délku archivu a počáteční adresu v archivační paměti. Pod těmito údaji je zobrazena velikost jednoho řádku archivu (Row size), celková délka archivu a další volná adresa v archivační paměti. S ohledem na minimalizování doby potřebné pro zápis řádku do archivační paměti je vhodné, aby velikost řádku byla mocninou 2 (8,16,32,64,128 B).","V dolní části dialogu se nachází tabulka signálů znázorňující napojení jednotlivých vstupů modulu. Pro každý vstup lze zadat jméno sloupce v tabulce, do které bude PC archiv zapisovat. Při použití tabulky typu DBase je délka názvu pole omezena na 10 znaků. Následující příklad znázorňuje použití modulu Logger pro archvaci 4 signálů každých 10 sekund. Blok Trigger nastaví na výstupu Y hodnotu 1 při každé změně desítek sekund (sekundy / 10). Výstup Index modulu Logger je přiveden na vstup modulu SaveData. Tím je zajištěno, že po případném výpadku napájení nebo jiném resetu PLC bude zápis archivu pokračovat na dalším volném řádku."],"tables":[]},{"name":"Move","category":"Main","group":"Other","title":"Kopíruje hodnotu typu int","formula":"Moves value X to Y when triggered","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Tr","input","Boolean","Trigger","Při přechodu z 0 do 1 se hodnota vstupu X uloží do výstupu Y","0"],["X","input","Int","X","Vstupní hodnota","0"],["Y","output","Int","Y","Poslední vyžádaná kopie vstupu X","-"]],"notes":["Modul sleduje stav vstupu Tr. Při výskytu náběžné hrany (přechodu z 0 do 1) zkopíruje hodnotu vstupu X do výstupu Y."],"tables":[]},{"name":"P3Menu","category":"Main","group":"Other","title":"Editor nabídky PLC Sybas P3 Modul nemá žádné vstupy ani výstupy. Slouží jen pro konfiguraci nabídky pomocí konfiguračního dialogového okna V levé části konfiguračního okna je zobrazena struktura nabídky. Tlačítko Add item přidá novou položku do nabídky. Add subitem rovněž vytvoří novou položku, ovšem zařadí ji do podnabídky vybrané položky. Tlačítka Move up a Move down přemisťují vybranou položku v rámci její úrovně. Poslední tlačítko Delete item smaže vybranou položku. Pravá část okna slouží k nastavení vlastností vybrané položky. Pole Text obsahuje text, který bude zobrazen v horním řádku displaye. Ve spodním řádku pak může být zobrazena hodnota proměnné (příp. parametru), kterou přiřadíte do pole Value. Se zobrazením této hodnoty souvisí zbývající pole a možnosti. Volba Read only znemožní editaci proměnné. Zaškrtnutí Use 1/K znamená, že se místo hodnoty K (vysvětleno níže) použije její převrácená (reciproká) hodnota. Možnost Change Q znamená, že po editaci hodnoty proměnné pomocí tlačítek PLC nebude změněna proměnná/parametr určená/ý polem Value. Místo ní se změní hodnota proměnné/parametru Q tak, aby zobrazená hodnota odpovídala hodnotě nastavené editací. Pole Min a Max vymezují editační rozsah proměnné/parametru. Hodnoty K a Q provádějí lineární transformaci Y=K.X+Q mezi zobrazenou hodnotou (Y) a proměnnou/parametrem (X). Do polí K a Q je možné vložit přímou hodnotu (v povoleném rozsahu) nebo je lze napojit na proměnné/parametry (pak má význam volba Change Q). Poslední pole Decimals určuje počet desetinných míst zobrazených na displayi. Tento modul může být v projektu použit jen jednou!","formula":"Menu designer","pins":[],"notes":["The module has no inputs or outputs. It only serves to configure the menu via its configuration dialog","The left part of the configuration window shows the menu structure. The Add item button adds a new item to the menu; Add submenu also creates a new item but places it in the submenu of the selected item. The Move up and Move down buttons move the selected item within its level. The last button, Delete item, deletes the selected item. The right part of the window is used to set the properties of the selected item. The Text field contains the text that will be displayed on the top line of the display. The bottom line can show the value of a variable (or parameter) which you assign to the Value field. The remaining fields and options relate to the display of that value. The Read only option prevents the variable from being edited. Checking Use 1/K means that instead of the value K (explained below) its reciprocal value is used. The Change Q option means that after editing the variable value using the PLC buttons, the variable/parameter given by the Value field will not be changed; instead the value of the variable/parameter Q is changed so that the displayed value corresponds to the value set by the edit. The Min and Max fields define the editing range of the variable/parameter. The values K and Q perform the linear transformation Y=K.X+Q between the displayed value (Y) and the variable/parameter (X). A direct value (within the permitted range) can be entered into the K and Q fields, or they can be connected to variables/parameters (in which case the Change Q option is meaningful). The last field, Decimals, determines the number of decimal places shown on the display.","The # character controls the position and formatting of the displayed value. By default the value is shown on the second line of the display, aligned fully to the right. If additional text is to be displayed after the value (e.g. a unit), the # character is used in place of the last digit of the displayed value. For example the text \"Tepl. dílna #°C\" displays the unit °C after the temperature.","If a certain minimum number of digits is to be displayed (leading zeros), that area is marked with the @ characters, e.g. \"Venkovní tepl. @@@#°C\".","The value can also be displayed in hexadecimal or binary notation using the character pair X# or B#. When editing two-state values (0/1), the following texts can be displayed instead of the numeric value:","0# OFF/ON 1# OFF/ON 2# NO/YES 3# FAULT/OK","This module may be used only once in a project!"],"tables":[]},{"name":"SaveData","category":"Main","group":"Other","title":"Ukládá/obnovuje data do/z FRAM","formula":"Stores/restores data into/from FRAM","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["I1","input","Long","I1","Ukládaná hodnota","0"],["Addr","parameter","Int","Address","FRAM address","0"]],"notes":["I2 volitelný vstup Long I2 Ukládaná hodnota 0 volitelný vstup Long ... Ukládaná hodnota 0 IN volitelný vstup Long IN Ukládaná hodnota 0 Int Addr parametr Address Počet vstupů tohoto modulu je uživatelsky nastavitelný.","Adresa FRAM 0 Modul SaveData v 1. cyklu procesu přečte z FRAM hodnoty uložené od adresy Addr a umístí je do proměnných připojených na vstupy I1 až IN. V dalších cyklech jsou naopak hodnoty těchto proměnných ukládány do FRAM na příslušné adresy."],"tables":[]},{"name":"Set","category":"Main","group":"Other","title":"Nastavení proměnných připojených na vstupy P1-Pn na hodnotu vstupu X","formula":"Set values of the pin X to the pins P1..Pn","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Long","Input","Vstupní hodnota","0"],["P1 - Pn","input","Long","P1 - Pn","Nastavované piny","0"]],"notes":["Pokud je vstup En = 1, dojde k zapsání hodnoty ze vstupu X do proměných (výstupů jiných modulů) připojených na vstupy P1-Pn. Počet vstupů N tohoto modulu je uživatelsky nastavitelný v rozsahu 1 - 126."],"tables":[]},{"name":"SystemCmd","category":"Main","group":"Other","title":"Provede systémový příkaz","formula":"Performs firmware-specific system command.","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0"],["Par1","input","Int","Parametr1","První parametr","0"],["Par1","input","Int","Parametr2","První parametr","0"],["Out","output","Int","Output","Výstupní hodnota","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0000"],["FW","output","Int","Output","Output value","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0001"],["Tmr","output","Int","Output","Output value","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0004"],["Par1","input","Int","Parametr1","První parametr","0"],["Tmr","output","Int","Output","Output value","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x000F"],["DoNum","input","Int","DO Number","Output number 0 - 23","0"],["Current","output","Int","Output","Output current value","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0010"],["Zr_U","input","Int","Zero U","Voltage limit (630 = 1 V)","0"],["Zr_I","input","Int","Zero I","Current limit (x 0.5 mA)","0"],["Out","output","Int","Output","Výstupní hodnota","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0020"],["BitNr","input","Int","Bit Number","Ordinal number of the bit being searched for","0"],["Inp","input","Long","Input","Input value","0"],["BitPos","output","Int","Bit Position","Position of the bit found","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0100"],["Adr","output","Int","Adresa","Address of the module on the D3Net network","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0101"],["Addr","input","Int","Address","Requested address","0"],["Lock","input","Int","Lock","Lock of the RowNet address","0"],["Adr","output","Int","Output","Address on the RowNet network","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0102"],["Dir","output","Bit","Output","Direction of the RowNet network (0 = left to right, 1 = right to left)","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0103"],["BkTmr","output","Int","Output","Output value","-"],["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Cmd","input","Int","Command","Kód požadované funkce","0x0104"],["Addr","input","Int","Address","Unit address","0"],["Count","input","Int","Count","Number of units","0"],["Out","output","Int","Output","Výstupní hodnota","-"]],"notes":["Modul SystemCmd provede funkci danou kódem na vstupu Cmd. Seznam dostupných funkcí závisí na typu zařízení.","Firmware Type Vrací typ Firmware Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0000 FW výstup Int Output Výstupní hodnota - Funkce 0x0000 vrátí na výstupu Fw typ firmware.","Firmware Version Vrací aktuální verzi Firmware Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0001 Tmr výstup Int Output Výstupní hodnota - Funkce 0x0000 vrátí na výstupu Ver aktuální verzi firmware.","Read Timer Čtení systémového časovače Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0004 Par1 vstup Int Parametr1 Nevyužito 0 Tmr výstup Int Output Výstupní hodnota - Funkce 0x0004 vrátí na výstupu Tmr aktuální hodnotu systémového časovače. Frekvence inkrementování činí u modulu P24 1 kHz. Zkouška zátěže logického výstupu Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x000F DoNum vstup Int DO Number Číslo výstupu 0 - 23 0 Current výstup Int Output Výstupní hodnota proudu - Funkce 0x0004 u modulu P24 slouží pro ověření připojení zátěže na výstupu daném hodnotou DoNum (0 - 23). Na krátkou dobu se sepne vybraný výstup a měří se proud protékající zátěží připojené k danému výstupu. Výsledný průměrný proud za tuto dobu se zapíše na výstup Current.","Nastavení mezí pro hlídání nulového napětí a proudu Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0010 Zr_U vstup Int Zero U Mez napětí (630 = 1 V) 0 Zr_I vstup Int Zero I Mez proudu (x 0,5 mA) 0 Out výstup Int Output Nevyužito - Funkce 0x0010 u modulu P24 nastaví meze pro hlídání nulového napětí a proudu u vypnutých logických výstupů. Pokud se na vypnutém výstupu objeví napětí nebo proud větší než nastavený limit, je takový výstupu označen chybou nulového napětí či proudu. Číslo prvního vypnutého výstupu s nenulovým napětím lze zjistit modulem ReadAI s číslem kanálu = 200. Obdobně číslo prvního vypnutého výstupu s nenulovým proudem lze zjistit modulem ReadAI s číslem kanálu = 201.","Hledání pozice nenulového bitu Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0020 BitNr vstup Int Bit Number Pořadí hledaného bitu 0 Inp vstup Long Input Vstupní hodnota 0 BitPos výstup Int Bit Position Pozice nalezeného bitu - Funkce 0x0020 hledá pozici prvního nenulového bitu ve slově na vstupu Inp zprava. Pokud žádný bit nenabývá hodnoty 1, je výsledná hodnotá = 0, jinak se na výstup BitPos zapíše číslo prvního nenulového bitu zprava v rozsahu 1 - 32. Vstupem BitNr lze určit pořadí hledaného bitu: 1 = první nenulový bit, 2 = druhý nenulový bit atd. V případě BitNr = 0 vrátí výstup horních 16 bitů hodnoty Imp. Čtení adresy modulu na síti DbNet Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0100 Adr výstup Int Adresa Adresa modulu na síti Dbnet - Funkce 0x0100 vrátí aktuální adresu modulu na síti Dbnet, obvykle v rozsahu 0 - 31.","Nastavení adresy na síti RowNet Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0101 Addr vstup Int Address Požadovaná adresa 0 Lock vstup Int Lock Zámek adresy sitě RowNet 0 Adr výstup Int Output Adresa na síti RowNet - Funkce 0x0101 umožňuje zjisti nebo nastavit adresu modul na síti RowNet a nastavit režim zámku této adresy. Pokud je vstup Address > 0 a program provádí první cyklus, je adresa sítě RowNet nastavena na hodnotu vstupu Address. Vstup Lock nastavuje režim zámku adresy: 0 = automatické číslování jednotek, 1 = automatické číslování jen směrem nahoru (při přidání jednotky, aby nedošlo k duplicitě adres), 2 = celkový zámek adresy.","RNet Direction Vrátí směr sítě RowNet Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0102 Dir výstup Bit Output Směr sítě RowNet (0 = zleva doprava, 1 = zprava doleva) - Funkce 0x0102 vrátí aktuální směr sítě RowNet. 0 značí směr číslování jednotek zleva doprava, 1 znamená směr obrácený Start Thread 3 Spuštění komunikačního vlákna Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0103 BkTmr výstup Int Output Výstupní hodnota - Funkce 0x0103 umožňuje zkrátit prodlevu mezi cykly komunikačního vlákna programu. Pokud je vlákno právě ve stavu prodlevy mezi jednotlivými cykly vlákna, vykonáním uvedené funkce se prodleva předčasě ukončí a vlákno se spustí ihned. Výstup BkTmr udává velikost zkrácení prodlevy.","Nastavení cílové jednotky na síti RowNet pro následující komunikační blok Popis vstupů a výstupů:","Zkratka Typ Datový typ Název Popis Výchozí hodnota En vstup Boolean Enabled Možnost zablokování funkce (=0..neprovádí se, =1..provádí se) 1 Cmd vstup Int Command Kód požadované funkce 0x0104 Addr vstup Int Address Adresa jednotky 0 Count vstup Int Count Počet jednotek 0 Out výstup Int Output Vrátí hodnotu vstupu Addr - Funkce 0x0104 umožňuje nastavení adresy a počtu jednotek pro čtení či zápis dalším blokem DbnXxxx. Pokud má následující komunikační blok horní byte adresy = 0x7F, použije se jako adresa cílové jednotky hodnota ze vstupu Addr tohoto bloku (přičtením 0x100 k adrese Addr se zajistí adresování všech jednotek od aktuální až po cílovou). Pokud má následující komunikační blok horní byte adresy = 0x7E, použije se jako adresa cílové jednotky hodnota ze vstupu Addr tohoto bloku a jako počet jednotek hodnota ze vstupu Count."],"tables":[]},{"name":"Trigger","category":"Main","group":"Other","title":"Sleduje změny hodnoty proměnné/parametru","formula":"Generates binary impulse whenever X is changed","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Int","X","Sledovaná hodnota","0"],["Y","output","Boolean","Y","Příznak změny","-"]],"notes":["Modul sleduje hodnotu připojenou na vstup X a při každé její změně nastaví na výstup Y logickou 1. Je-li hodnota stejná jako v předchozím cyklu procesu je výstup Y vynulován."],"tables":[]},{"name":"FSwitch","category":"Main","group":"Switches","title":"Přepínač mezi hodnotami typu Float","formula":"Switches between values of float data type, depending on switch state","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Sw","input","Int","Switch","Přepínač","0"],["X0 - Xn","input","Float","X0 - Xn","Vstupy hodnot","0"],["Y","output","Float","Out","Výstup","-"]],"notes":["Modul nastavuje výstup Y v závislosti na stavu přepínače Sw. Pokud je Sw=0, pak se na výstup Y kopíruje hodnota X0. Pokud je Sw=1, pak se na výstup Y kopíruje hodnota X1 atd. V případě, že je vstup Sw mimo rozsah 0 až (N-1), je výstup Y vynulován. Počet vstupů N tohoto modulu je uživatelsky nastavitelný v rozsahu 1 - 16."],"tables":[]},{"name":"ISwitch","category":"Main","group":"Switches","title":"Přepínač mezi hodnotami typu Int","formula":"Switches between values of int data type, depending on switch state","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Sw","input","Int","Switch","Přepínač","0"],["X0 - Xn","input","Int","X0 - Xn","Vstupy hodnot","0"],["Y","output","Int","Out","Výstup","-"]],"notes":["Modul nastavuje výstup Y v závislosti na stavu přepínače Sw. Pokud je Sw=0, pak se na výstup Y kopíruje hodnota X0. Pokud je Sw=1, pak se na výstup Y kopíruje hodnota X1 atd. V případě, že je vstup Sw mimo rozsah 0 až (N-1), je výstup Y vynulován. Počet vstupů N tohoto modulu je uživatelsky nastavitelný v rozsahu 1 - 16."],"tables":[]},{"name":"LSwitch","category":"Main","group":"Switches","title":"Přepínač mezi hodnotami typu Long","formula":"Switches between values of long data type, depending on switch state","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Sw","input","Int","Switch","Přepínač","0"],["X0 - Xn","input","Long","X0 - Xn","Vstupy hodnot","0"],["Y","output","Long","Out","Výstup","-"]],"notes":["Modul nastavuje výstup Y v závislosti na stavu přepínače Sw. Pokud je Sw=0, pak se na výstup Y kopíruje hodnota X0. Pokud je Sw=1, pak se na výstup Y kopíruje hodnota X1 atd. V případě, že je vstup Sw mimo rozsah 0 až (N-1), je výstup Y vynulován. Počet vstupů N tohoto modulu je uživatelsky nastavitelný v rozsahu 1 - 16."],"tables":[]},{"name":"DateTime","category":"Main","group":"Timers","title":"Aktuální datum a čas","formula":"Returns current day and time","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Offs","input","Long","Offset","Optional offset input in seconds, added to the system time, e.g. for conversion between UTC and local time","0"],["D","output","Long","Day","Počet dnů od 1.1.1980","-"],["H","output","Int","Hour","Hodina","-"],["M","output","Int","Minute","Minuta","-"],["S","output","Int","Second","Vteřina","-"],["DOW","output","Int","DayOfWeek","Den týdne (=0..pondělí, =1..úterý, ..., =6..neděle)","-"],["SOD","output","Long","SecondOfDay","Sekunda od půlnoci (0 - 86399)","-"]],"notes":["Modul čte nastavené datum a čas PLC a nastavuje odpovídající hodnoty výstupů. V konfiguračním dialogu modulu lze povolit výstupní pin SOD (sekundy od půlnoci)."],"tables":[]},{"name":"PulseGen","category":"Main","group":"Timers","title":"Generátor pulzů","formula":"Generates pulses","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Act","input","Boolean","Active","Aktivuje generování pulzů","0"],["TOn","parameter","Int","Time On","Délka pulzu v cyklech","1"],["TOff","parameter","Int","Time Off","Doba mezi pulzy v cyklech","1"],["Cnt","output","Int","Counter","Čítač cyklů","-"],["Out","output","Boolean","Output","Generované pulzy","-"]],"notes":["Je-li aktivní (=1) vstup Act, pak se na výstupu Out generují pulzy o délce TOn s prodlevou TOff. Hodnoty TOn a TOff znamenají počet cyklů. Pokud je modul umístěn v procesu \"Timer 1s\", pak budou tyto hodnoty v sekundách. Výstup Cnt funguje jako čítač cyklů. Když jeho hodnota dosáhne nebo přesáhne (např. při změně TOn nebo TOff) součet TOn+TOff, je vynulován.","Pokud je Act=0, jsou oba výstupy vynulovány."],"tables":[]},{"name":"PulseLen","category":"Main","group":"Timers","title":"Měří délku pulzu","formula":"Measures length of pulse","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["In","input","Boolean","Input","Vstup","0"],["Len","output","Int","Length","Čítač cyklů","-"]],"notes":["Modul měří délku pulzu přivedeného na vstup In. Spolu s náběžnou hranou (přechodem z 0 do 1) na vstupu In začne počítání počtu cyklů procesu na výstupu Len. Toto počítání se zastaví s vynulováním vstupu In. Hodnota na výstupu Len zůstane zachována do výskytu dalšího pulzu."],"tables":[]},{"name":"SinglePulse","category":"Main","group":"Timers","title":"Generuje pulz požadované délky","formula":"Generates single pulse","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["Tr","input","Boolean","Trigger","Spouštěč","0"],["TOn","parameter","Int","Time On","Délka pulzu v cyklech","1"],["Cnt","output","Int","Counter","Čítač cyklů","-"],["Out","output","Boolean","Output","Generované pulzy","-"]],"notes":["Pokud se na vstupu Tr vyskytne náběžná hrana (přechod z 0 do 1), bude na výstupu Out logická 1 po dobu TOn cyklů procesu. Výstup Cnt slouží jako čítač pulzů, který během aktivity pulzu nabývá hodnot 1 až TOn. Poté bude spolu s výstupem Out vynulován."],"tables":[]},{"name":"Timer","category":"Main","group":"Timers","title":"Vícefunkční časovač","formula":"Timer","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["In","input","Boolean","Input","Vstupní signál. Hrana 0-->1 spouští časování","0"],["Rst","input","Boolean","Reset","Log. 1 na vstupu Reset nuluje časovač","0"],["Dly","parameter","Int","Delay","Délka pulzu v cyklech","1"],["Cnt","output","Int","Counter","Čítač cyklů","-"],["Out","output","Boolean","Output","Generované pulzy","-"]],"notes":["Časovač pracuje v jednom ze 4 režimů, které se volí v konfiguračním dialogu:","Režimy Fixed Pulse a Truncated Pulse generují puls délky Delay cyklů procesu. případě, že během časování přejde vstup do úrovně 0. V režimu Truncated Pulse je impuls zkrácen v V režimech On-Delay a On-Delay Continuous je vstupní puls zpožděn o Delay cyklů procesu. V režimu On-Delay se výstupní impuls ukončí přechodem vstupu In do 0. V režimu On-Delay Continuous se výstupní impuls ukončí až hodnotou 1 na vstupu Reset. Vstup Input a výstup Output je možno invertovat.","Výstup Counter nabývá v klidu hodnoty 0, během časování pak roste od 1 až po hodnotu Delay."],"tables":[]},{"name":"Div","category":"Math","group":"","title":"Celočíselné dělení hodnoty typu Long hodnotou typu Int","formula":"Y = A / B","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["A","input","Long","A","První operand","0"],["B","input","Int","B","Druhý operand","0"],["Y","output","Long","Y","Výsledek operace Y = A / B","-"],["Mod","output","Int","Modulo","Zbytek po dělení Mod = A % B","-"]],"notes":["Modul celočíselně vydělí hodnotu A a hodnotou B a výsledek uloží do výstupu Y. V konfiguračním dialogu lze aktivovat volitelný výstup zbytku po dělení Mod."],"tables":[]},{"name":"FAbs","category":"Math","group":"","title":"Absolutní hodnota typu Float","formula":"Y = Abs(X)","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X","input","Float","X","Vstupní hodnota","0"],["Y","output","Float","Y","Výsledek operace Y=|X|","-"]],"notes":["Modul vypočítá absolutní hodnotu vstupu X a výsledek uloží do výstupu Y. Je-li X>=0, pak Y=X, v opačném případě (X<0) je Y=-X"],"tables":[]},{"name":"FAdd","category":"Math","group":"","title":"Součet hodnot typu Float","formula":"Y = X0 + X1 ...","pins":[["En","input","Boolean","Enabled","Možnost zablokování funkce (=0..neprovádí se, =1..provádí se)","1"],["X0","input","Float","X0","První operand","0"